 renderHealth(){U.setText('health-network',navigator.onLine?'ONLINE':'OFFLINE');U.setText('health-firebase',T.Data.connected?'CONNECTED':'DISCONNECTED');U.setText('health-queue',T.Data.pending||0);U.setText('health-audio',this.audioUnlocked?'READY':'LOCKED');U.setText('health-version',T.VERSION);U.setText('health-root',T.ROOT)},heartbeat(){clearInterval(this.hb);const send=()=>{if(!T.Data.ready||!T.Auth.user)return;T.Data.db.ref(`${T.ROOT}/health/${T.Auth.user.uid}`).set({uid:T.Auth.user.uid,name:T.Auth.profile?.displayName||T.Auth.user.email,role:T.Auth.role(),online:navigator.onLine,lastSeen:Date.now(),tab:this.currentTab,pending:T.Data.pending}).catch(()=>{})};send();this.hb=setInterval(send,30000)},
 exportBackup(){const data={type:'TOPKEY_SPORT_VNEXT_BACKUP',sport:S.key,version:T.VERSION,exportedAt:new Date().toISOString(),tournamentId:T.Data.tid,data:this.state};U.download(`Topkey_${S.key}_Backup_${this.localDate()}.json`,new Blob([JSON.stringify(data,null,2)],{type:'application/json'}))},async importBackup(file){if(!file)return;try{const j=JSON.parse(await file.text());if(j.sport&&j.sport!==S.key)throw new Error('Backup thuộc môn '+j.sport);if(!await U.confirmDanger('Nhập backup','Dữ liệu hiện tại của các nhánh trong backup sẽ bị ghi đè.','NHẬP'))return;const up={},d=j.data||j;['config','teams','matches','courts','activeMatches','finance','announcements','registrations','commentary'].forEach(k=>{if(d[k]!=null)up[T.Data.path(k)]=d[k]});await T.Data.queueMulti(up,{type:'IMPORT_BACKUP'});await T.Data.audit('IMPORT_BACKUP','tournament',T.Data.tid,null,{file:file.name})}catch(e){U.toast(e.message,'err')}},
